1	@tailwind base;
2	@tailwind components;
3	@tailwind utilities;
4	
5	/* ─── Editorial Design Tokens ──────────────────────────────────────────────── */
6	
7	:root {
8	  /* Color — warm paper editorial palette */
9	  --color-paper:      #f5f1eb;
10	  --color-ink:        #1a1714;
11	  --color-muted:      #6b6560;
12	  --color-faint:      #c8c2ba;
13	  --color-oxblood:    #7a1d1d;
14	  --color-accent:     #9b3b1e;
15	  --color-hairline:   #ddd8d0;
16	  --color-surface:    #ede9e2;
17	
18	  /* Typography */
19	  --font-serif:       'Spectral', 'Plantin', 'Georgia', serif;
20	  --font-sans:        'Inter', system-ui, -apple-system, sans-serif;
21	
22	  /* Type scale (fluid) */
23	  --text-xs:          0.75rem;
24	  --text-sm:          0.875rem;
25	  --text-base:        1.0625rem;
26	  --text-lg:          1.25rem;
27	  --text-xl:          1.5rem;
28	  --text-2xl:         2rem;
29	  --text-3xl:         2.75rem;
30	  --text-4xl:         3.75rem;
31	  --text-5xl:         5rem;
32	
33	  /* Leading */
34	  --leading-tight:    1.15;
35	  --leading-snug:     1.35;
36	  --leading-prose:    1.7;
37	
38	  /* Tracking */
39	  --tracking-tight:   -0.02em;
40	  --tracking-wide:    0.08em;
41	  --tracking-caps:    0.12em;
42	
43	  /* Spacing rhythm */
44	  --space-1:          0.25rem;
45	  --space-2:          0.5rem;
46	  --space-3:          0.75rem;
47	  --space-4:          1rem;
48	  --space-6:          1.5rem;
49	  --space-8:          2rem;
50	  --space-12:         3rem;
51	  --space-16:         4rem;
52	  --space-24:         6rem;
53	  --space-32:         8rem;
54	  --space-48:         12rem;
55	
56	  /* Max-width column */
57	  --col-prose:        68ch;
58	  --col-wide:         90rem;
59	
60	  /* Transitions */
61	  --ease-out:         cubic-bezier(0.16, 1, 0.3, 1);
62	  --duration-fast:    120ms;
63	  --duration-base:    240ms;
64	  --duration-slow:    400ms;
65	}
66	
67	/* ─── Base Layer ────────────────────────────────────────────────────────────── */
68	
69	@layer base {
70	  *,
71	  *::before,
72	  *::after {
73	    box-sizing: border-box;
74	    margin: 0;
75	    padding: 0;
76	  }
77	
78	  html {
79	    scroll-behavior: smooth;
80	    -webkit-text-size-adjust: 100%;
81	    text-size-adjust: 100%;
82	  }
83	
84	  body {
85	    font-family: var(--font-serif);
86	    font-size: var(--text-base);
87	    line-height: var(--leading-prose);
88	    background-color: var(--color-paper);
89	    color: var(--color-ink);
90	    overflow-x: hidden;
91	    /* Font rendering */
92	    -webkit-font-smoothing: antialiased;
93	    -moz-osx-font-smoothing: grayscale;
94	    font-feature-settings: 'kern' 1, 'liga' 1, 'onum' 1;
95	    /* Balanced text wrapping (Chrome 114+, Firefox 121+) */
96	    text-wrap: pretty;
97	  }
98	
99	  /* Headings default to serif */
100	  h1, h2, h3, h4, h5, h6 {
101	    font-family: var(--font-serif);
102	    font-weight: 500;
103	    letter-spacing: var(--tracking-tight);
104	    line-height: var(--leading-tight);
105	    text-wrap: balance;
106	    color: var(--color-ink);
107	  }
108	
109	  /* Focused elements — visible, consistent, branded */
110	  :focus-visible {
111	    outline: 2px solid var(--color-oxblood);
112	    outline-offset: 3px;
113	    border-radius: 2px;
114	  }
115	
116	  /* Remove outline for mouse users */
117	  :focus:not(:focus-visible) {
118	    outline: none;
119	  }
120	
121	  /* Links */
122	  a {
123	    color: inherit;
124	    text-decoration: none;
125	  }
126	
127	  /* Images */
128	  img,
129	  picture,
130	  video,
131	  canvas,
132	  svg {
133	    display: block;
134	    max-width: 100%;
135	  }
136	
137	  /* Form elements inherit typography */
138	  input,
139	  button,
140	  textarea,
141	  select {
142	    font: inherit;
143	  }
144	
145	  /* Horizontal rule — hairline */
146	  hr {
147	    border: none;
148	    border-top: 1px solid var(--color-hairline);
149	  }
150	}
151	
152	/* ─── Skip Link ─────────────────────────────────────────────────────────────── */
153	
154	.skip-link {
155	  position: absolute;
156	  top: -100%;
157	  left: var(--space-4);
158	  z-index: 9999;
159	  padding: var(--space-2) var(--space-4);
160	  background: var(--color-ink);
161	  color: var(--color-paper);
162	  font-family: var(--font-sans);
163	  font-size: var(--text-sm);
164	  font-weight: 600;
165	  letter-spacing: var(--tracking-caps);
166	  text-transform: uppercase;
167	  text-decoration: none;
168	  border-radius: 0 0 4px 4px;
169	  transition: top var(--duration-fast) var(--ease-out);
170	}
171	
172	.skip-link:focus {
173	  top: 0;
174	  outline: 2px solid var(--color-oxblood);
175	  outline-offset: 2px;
176	}
177	
178	/* ─── Reduced Motion ────────────────────────────────────────────────────────── */
179	
180	@media (prefers-reduced-motion: reduce) {
181	  *,
182	  *::before,
183	  *::after {
184	    animation-duration: 0.01ms !important;
185	    animation-iteration-count: 1 !important;
186	    transition-duration: 0.01ms !important;
187	    scroll-behavior: auto !important;
188	  }
189	}
190	
191	/* ─── Utility Classes ───────────────────────────────────────────────────────── */
192	
193	@layer utilities {
194	  .font-serif   { font-family: var(--font-serif); }
195	  .font-sans    { font-family: var(--font-sans); }
196	
197	  .text-paper   { color: var(--color-paper); }
198	  .text-ink     { color: var(--color-ink); }
199	  .text-muted   { color: var(--color-muted); }
200	  .text-oxblood { color: var(--color-oxblood); }
201	  .text-accent  { color: var(--color-accent); }
202	
203	  .bg-paper     { background-color: var(--color-paper); }
204	  .bg-surface   { background-color: var(--color-surface); }
205	  .bg-ink       { background-color: var(--color-ink); }
206	
207	  .border-hairline { border-color: var(--color-hairline); }
208	
209	  .tracking-caps   { letter-spacing: var(--tracking-caps); }
210	  .tracking-tight  { letter-spacing: var(--tracking-tight); }
211	  .tracking-wide   { letter-spacing: var(--tracking-wide); }
212	
213	  .leading-prose  { line-height: var(--leading-prose); }
214	  .leading-tight  { line-height: var(--leading-tight); }
215	  .leading-snug   { line-height: var(--leading-snug); }
216	
217	  .col-prose  { max-width: var(--col-prose); }
218	  .col-wide   { max-width: var(--col-wide); }
219	}
