import React from 'react';

/**
 * Opening spread — the lede section of the one-page portfolio.
 * Book-like: no cards, no icons, no gradients, no shadows.
 */
export default function OpeningSpread() {
  return (
    <section
      id="about"
      aria-labelledby="about-heading"
      style={{
        backgroundColor: 'var(--color-paper)',
        padding: 'var(--space-32) var(--space-8) var(--space-24)',
        borderBottom: '1px solid var(--color-hairline)',
      }}
    >
      <div style={{ maxWidth: 'var(--col-prose)', margin: '0 auto' }}>
        <p
          style={{
            fontFamily: 'var(--font-sans)',
            fontSize: 'var(--text-xs)',
            letterSpacing: 'var(--tracking-caps)',
            textTransform: 'uppercase',
            color: 'var(--color-muted)',
            marginBottom: 'var(--space-8)',
          }}
        >
          Software Engineer &mdash; Toronto, Canada
        </p>

        <h2
          id="about-heading"
          style={{
            fontFamily: 'var(--font-serif)',
            fontSize: 'var(--text-4xl)',
            fontWeight: 300,
            lineHeight: 'var(--leading-tight)',
            letterSpacing: 'var(--tracking-tight)',
            color: 'var(--color-ink)',
            margin: '0 0 var(--space-8)',
          }}
        >
          Building things that feel&nbsp;right.
        </h2>

        <p
          style={{
            fontFamily: 'var(--font-serif)',
            fontSize: 'var(--text-lg)',
            lineHeight: 'var(--leading-prose)',
            color: 'var(--color-ink)',
            maxWidth: '52ch',
            margin: 0,
          }}
        >
          Full-stack developer with a focus on clean interfaces, thoughtful systems, and work that
          holds up.
        </p>
      </div>
    </section>
  );
}

import React from 'react';

const labelStyle = {
  fontFamily: 'var(--font-sans)',
  fontSize: 'var(--text-xs)',
  letterSpacing: 'var(--tracking-caps)',
  textTransform: 'uppercase',
  color: 'var(--color-muted)',
  marginBottom: 'var(--space-4)',
};

const headingStyle = {
  fontFamily: 'var(--font-serif)',
  fontSize: 'var(--text-3xl)',
  fontWeight: 300,
  lineHeight: 'var(--leading-tight)',
  letterSpacing: 'var(--tracking-tight)',
  color: 'var(--color-ink)',
  margin: '0 0 var(--space-16)',
};

/**
 * Reusable editorial section shell.
 * Props:
 *   id        — anchor id for the <section>
 *   label     — small-caps eyebrow label (e.g. "Experience")
 *   heading   — display heading (e.g. "Work")
 *   surface   — "paper" | "surface" (defaults to "paper")
 *   children  — content slot filled by later slices
 */
export default function SectionShell({ id, label, heading, surface = 'paper', children }) {
  const headingId = `${id}-heading`;
  const bg = surface === 'surface' ? 'var(--color-surface)' : 'var(--color-paper)';

  return (
    <section
      id={id}
      aria-labelledby={headingId}
      style={{
        backgroundColor: bg,
        padding: 'var(--space-24) var(--space-8)',
        borderBottom: '1px solid var(--color-hairline)',
      }}
    >
      <div style={{ maxWidth: 'var(--col-prose)', margin: '0 auto' }}>
        <p style={labelStyle}>{label}</p>
        <h2 id={headingId} style={headingStyle}>
          {heading}
        </h2>
        {children}
      </div>
    </section>
  );
}

import React from 'react';
import OpeningSpread from './editorial/OpeningSpread';
import SectionShell from './editorial/SectionShell';

export default function EditorialPortfolio() {
  return (
    <>
      {/* Accessible skip link — positioned off-screen until focused */}
      <a href="#main" className="skip-link">
        Skip to main content
      </a>

      {/* ── Name corner / identity header ───────────────────────────────────── */}
      <header
        id="top"
        aria-label="Site identity"
        style={{
          backgroundColor: 'var(--color-paper)',
          borderBottom: '1px solid var(--color-hairline)',
          padding: 'var(--space-6) var(--space-8)',
        }}
      >
        <div
          style={{
            maxWidth: 'var(--col-wide)',
            margin: '0 auto',
            display: 'flex',
            alignItems: 'baseline',
            gap: 'var(--space-4)',
          }}
        >
          <span
            aria-hidden="true"
            style={{
              fontFamily: 'var(--font-serif)',
              fontSize: 'var(--text-xs)',
              letterSpacing: 'var(--tracking-caps)',
              textTransform: 'uppercase',
              color: 'var(--color-muted)',
            }}
          >
            Portfolio
          </span>
          <h1
            data-identity
            style={{
              fontFamily: 'var(--font-serif)',
              fontSize: 'var(--text-2xl)',
              fontWeight: 400,
              letterSpacing: 'var(--tracking-tight)',
              color: 'var(--color-ink)',
              lineHeight: 'var(--leading-tight)',
              margin: 0,
            }}
          >
            Aatif Siddiqui
          </h1>
          <nav
            aria-label="Page sections"
            style={{
              marginLeft: 'auto',
              display: 'flex',
              gap: 'var(--space-6)',
            }}
          >
            {['About', 'Experience', 'Projects', 'Education', 'Skills'].map((label) => (
              <a
                key={label}
                href={`#${label.toLowerCase()}`}
                style={{
                  fontFamily: 'var(--font-sans)',
                  fontSize: 'var(--text-sm)',
                  letterSpacing: 'var(--tracking-wide)',
                  textTransform: 'uppercase',
                  color: 'var(--color-muted)',
                  textDecoration: 'none',
                  transition: 'color var(--transition-base)',
                }}
                onMouseEnter={(e) => (e.currentTarget.style.color = 'var(--color-ink)')}
                onMouseLeave={(e) => (e.currentTarget.style.color = 'var(--color-muted)')}
              >
                {label}
              </a>
            ))}
          </nav>
        </div>
      </header>

      {/* ── Main content ────────────────────────────────────────────────────── */}
      <main id="main" tabIndex={-1}>
        <OpeningSpread />

        <SectionShell id="experience" label="Experience" heading="Work" surface="paper" />

        <SectionShell id="projects" label="Projects" heading="Selected work" surface="surface" />

        <SectionShell id="education" label="Education" heading="Formation" surface="paper" />

        <SectionShell id="skills" label="Skills" heading="Craft" surface="surface" />
      </main>

      {/* ── Footer / colophon ───────────────────────────────────────────────── */}
      <footer
        aria-label="Colophon"
        style={{
          backgroundColor: 'var(--color-ink)',
          color: 'var(--color-faint)',
          padding: 'var(--space-12) var(--space-8)',
          textAlign: 'center',
        }}
      >
        <p
          style={{
            fontFamily: 'var(--font-sans)',
            fontSize: 'var(--text-xs)',
            letterSpacing: 'var(--tracking-wide)',
            textTransform: 'uppercase',
            margin: 0,
          }}
        >
          Aatif Siddiqui &mdash; {new Date().getFullYear()}
        </p>
      </footer>
    </>
  );
}

import React from 'react';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';
import EditorialPortfolio from '../components/EditorialPortfolio';

/**
 * Smoke tests for the editorial shell.
 * These run after every build to catch legacy imports or missing sections.
 */

describe('EditorialPortfolio — section anchors', () => {
  beforeEach(() => {
    render(<EditorialPortfolio />);
  });

  it('renders the identity heading with "Aatif"', () => {
    const h1 = screen.getByRole('heading', { level: 1 });
    expect(h1).toHaveTextContent('Aatif');
  });

  it('renders the #about opening spread section', () => {
    expect(document.getElementById('about')).toBeInTheDocument();
  });

  it('renders the #experience section', () => {
    expect(document.getElementById('experience')).toBeInTheDocument();
  });

  it('renders the #projects section', () => {
    expect(document.getElementById('projects')).toBeInTheDocument();
  });

  it('renders the #education section', () => {
    expect(document.getElementById('education')).toBeInTheDocument();
  });

  it('renders the #skills section', () => {
    expect(document.getElementById('skills')).toBeInTheDocument();
  });

  it('renders the colophon footer', () => {
    expect(screen.getByRole('contentinfo')).toBeInTheDocument();
  });

  it('renders a skip link targeting #main', () => {
    const skipLink = screen.getByText(/skip to main content/i);
    expect(skipLink).toHaveAttribute('href', '#main');
  });

  it('renders the lede headline', () => {
    expect(screen.getByText(/building things that feel/i)).toBeInTheDocument();
  });
});

describe('EditorialPortfolio — no legacy terminal visuals', () => {
  it('does not import matrix or terminal components at the component level', () => {
    // Read the source file content and assert no terminal/matrix references
    const fs = require('fs');
    const path = require('path');
    const src = fs.readFileSync(
      path.resolve(__dirname, '../components/EditorialPortfolio.jsx'),
      'utf8'
    );
    expect(src).not.toMatch(/matrix/i);
    expect(src).not.toMatch(/terminal/i);
    expect(src).not.toMatch(/cosmic/i);
    expect(src).not.toMatch(/rain/i);
    expect(src).not.toMatch(/framer.motion/i);
    expect(src).not.toMatch(/gsap/i);
    expect(src).not.toMatch(/lenis/i);
  });
});
